import type { NextApiRequest, NextApiResponse } from "next";
import { prisma } from "@/lib/db";
import { createAttachmentReadStream } from "@/lib/uploads";

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== "GET") {
    res.setHeader("Allow", "GET");
    return res.status(405).json({ error: "Method not allowed" });
  }

  const id = String(req.query.id ?? "");
  const attachment = await prisma.attachment.findUnique({
    where: { id },
    include: { message: true }
  });

  if (
    !attachment ||
    attachment.deletedAt ||
    !attachment.messageId ||
    attachment.message?.deletedAt ||
    (attachment.expiresAt && attachment.expiresAt.getTime() <= Date.now())
  ) {
    return res.status(404).json({ error: "Attachment expired or not found" });
  }

  res.setHeader("Content-Type", attachment.mimeType);
  res.setHeader("Content-Length", String(attachment.byteSize));
  res.setHeader("X-Content-Type-Options", "nosniff");
  res.setHeader("Content-Disposition", `${attachment.kind === "pdf" ? "attachment" : "inline"}; filename="${safeDownloadName(attachment.originalName)}"`);
  res.setHeader("Cache-Control", "private, max-age=300");

  createAttachmentReadStream(attachment.storedName)
    .on("error", () => {
      if (!res.headersSent) res.status(404).end("Attachment not found");
      else res.end();
    })
    .pipe(res);
}

function safeDownloadName(name: string) {
  return name.replace(/["\r\n\\]/g, "_").slice(0, 180) || "attachment";
}

import type { NextApiRequest, NextApiResponse } from "next";
import { clearSessionCookie, getCurrentUser, getSessionToken, hashToken, touchUserActivity } from "@/lib/auth";
import { prisma } from "@/lib/db";
import { sanitizeNickname } from "@/server/rooms";
import { getAccountStorageUsed } from "@/lib/uploads";
import { isSiteAdminEmail } from "@/lib/siteAdmin";

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === "GET") {
    const user = await getCurrentUser(req);
    if (user) await touchUserActivity(user.id);
    const storageUsedBytes = user ? await getAccountStorageUsed(user.id) : 0;
    return res.status(200).json({
      user: user
        ? { id: user.id, email: user.email, nickname: user.nickname, storageUsedBytes, isSiteAdmin: isSiteAdminEmail(user.email) }
        : null
    });
  }

  if (req.method === "DELETE") {
    const token = getSessionToken(req);
    if (token) {
      await prisma.userSession.deleteMany({ where: { tokenHash: hashToken(token) } });
    }
    clearSessionCookie(res);
    return res.status(200).json({ ok: true });
  }

  if (req.method === "PATCH") {
    const user = await getCurrentUser(req);
    if (!user) return res.status(401).json({ error: "Sign in first" });

    const nickname = sanitizeNickname(String(req.body.nickname ?? ""));
    if (!nickname) return res.status(400).json({ error: "Nickname is required" });

    const updated = await prisma.user.update({
      where: { id: user.id },
      data: { nickname }
    });

    await prisma.roomMember.updateMany({
      where: { identityId: `user:${user.id}` },
      data: { nickname }
    });

    return res.status(200).json({
      user: {
        id: updated.id,
        email: updated.email,
        nickname: updated.nickname,
        storageUsedBytes: await getAccountStorageUsed(updated.id),
        isSiteAdmin: isSiteAdminEmail(updated.email)
      }
    });
  }

  res.setHeader("Allow", "GET, PATCH, DELETE");
  return res.status(405).json({ error: "Method not allowed" });
}

import type { NextApiRequest, NextApiResponse } from "next";
import { createSession, normalizeEmail, setSessionCookie, touchUserActivity, verifyPassword } from "@/lib/auth";
import { checkRateLimit } from "@/lib/rateLimit";
import { prisma } from "@/lib/db";
import { getAccountStorageUsed } from "@/lib/uploads";
import { isSiteAdminEmail } from "@/lib/siteAdmin";

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== "POST") {
    res.setHeader("Allow", "POST");
    return res.status(405).json({ error: "Method not allowed" });
  }

  const email = normalizeEmail(String(req.body.email ?? ""));
  const password = String(req.body.password ?? "");
  const limit = checkRateLimit(`signin:${email || req.socket.remoteAddress}`, 10, 15 * 60 * 1000);
  if (!limit.allowed) return res.status(429).json({ error: "Too many signin attempts" });

  const user = await prisma.user.findUnique({ where: { email } });
  if (!user || !verifyPassword(password, user.passwordHash)) {
    return res.status(401).json({ error: "Invalid email or password" });
  }

  const session = await createSession(user.id);
  await touchUserActivity(user.id);
  setSessionCookie(res, session.token, session.expiresAt);
  return res.status(200).json({
    user: {
      id: user.id,
      email: user.email,
      nickname: user.nickname,
      storageUsedBytes: await getAccountStorageUsed(user.id),
      isSiteAdmin: isSiteAdminEmail(user.email)
    }
  });
}

import type { NextApiRequest, NextApiResponse } from "next";
import { createSession, hashPassword, normalizeEmail, setSessionCookie } from "@/lib/auth";
import { checkRateLimit } from "@/lib/rateLimit";
import { prisma } from "@/lib/db";
import { sanitizeNickname } from "@/server/rooms";
import { isSiteAdminEmail } from "@/lib/siteAdmin";

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== "POST") {
    res.setHeader("Allow", "POST");
    return res.status(405).json({ error: "Method not allowed" });
  }

  const email = normalizeEmail(String(req.body.email ?? ""));
  const nickname = sanitizeNickname(String(req.body.nickname ?? ""));
  const password = String(req.body.password ?? "");

  const limit = checkRateLimit(`signup:${email || req.socket.remoteAddress}`, 5, 60 * 60 * 1000);
  if (!limit.allowed) return res.status(429).json({ error: "Too many signup attempts" });

  if (!email.includes("@") || email.length > 254) return res.status(400).json({ error: "Enter a valid email" });
  if (!nickname) return res.status(400).json({ error: "Nickname is required" });
  if (password.length < 8) return res.status(400).json({ error: "Password must be at least 8 characters" });

  try {
    const user = await prisma.user.create({
      data: {
        email,
        nickname,
        passwordHash: hashPassword(password)
      }
    });
    const session = await createSession(user.id);
    setSessionCookie(res, session.token, session.expiresAt);
    return res.status(201).json({ user: publicUser(user) });
  } catch {
    return res.status(409).json({ error: "An account with that email already exists" });
  }
}

function publicUser(user: { id: string; email: string; nickname: string }) {
  return { id: user.id, email: user.email, nickname: user.nickname, storageUsedBytes: 0, isSiteAdmin: isSiteAdminEmail(user.email) };
}

